// Single source of truth for the trailer's timing. All values are seconds;
// `f()` converts them to frames at 60 FPS. Every scene boundary lands on a
// beat of the 120 BPM score generated by scripts/make-audio.mjs.
export const FPS = 60;
export const DURATION_SEC = 60;
export const DURATION_FRAMES = FPS * DURATION_SEC;

export const f = (sec: number) => Math.round(sec * FPS);

export const SCENES = {
  hook: [0, 5],
  meet: [5, 10],
  versions: [10, 17],
  mods: [17, 24],
  songs: [24, 31],
  vault: [31, 38],
  diagnostics: [38, 45],
  montage: [45, 52],
  finale: [52, 60],
} as const;

export type SceneName = keyof typeof SCENES;
